      "name": "Finset.prod_Ico_id_eq_factorial",
      "module_name": "Mathlib.Algebra.BigOperators.Intervals",
      "kind": "theorem",
      "type": "∀ (n : ℕ), ∏ x ∈ Finset.Ico 1 (n + 1), x = n.factorial"
    },
    {
      "name": "Nat.ascFactorial_eq_prod_range",
      "module_name": "Mathlib.Data.Nat.Factorial.BigOperators",
      "kind": "theorem",
      "type": "∀ (n k : ℕ), n.ascFactorial k = ∏ i ∈ Finset.range k, (n + i)"
    },
    {
      "name": "Finset.pow_eq_prod_const",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} [inst : CommMonoid M] (b : M) (n : ℕ), b ^ n = ∏ _k ∈ Finset.range n, b"
    }
  ]
}

